export function DayView({
  dateLabel = "{{dateLabel}}",
  date = "{{date}}",
  eventTitle = "{{eventTitle}}",
  density = "{{density}}",
  accent = "{{accent}}",
}) {
  const pad = density === "Compact" ? "5px 12px" : "10px 12px";
  const rows = [
    { hour: "9:00", event: null },
    { hour: "10:00", event: eventTitle },
    { hour: "11:00", event: null },
    { hour: "12:00", event: null },
  ];
  return (
    <table style={{ borderCollapse: "collapse", width: 340, font: "14px/1.4 system-ui, sans-serif", color: "#241430", background: "#FAF7F2" }}>
      <caption style={{ textAlign: "left", fontWeight: 700, paddingBottom: 10 }}><time dateTime={date}>{dateLabel}</time></caption>
      <thead>
        <tr><th scope="col" style={{ textAlign: "left", padding: pad, borderBottom: "1px solid #24143020" }}>Time</th><th scope="col" style={{ textAlign: "left", padding: pad, borderBottom: "1px solid #24143020" }}>Event</th></tr>
      </thead>
      <tbody>
        {rows.map((r) => (
          <tr key={r.hour}>
            <th scope="row" style={{ fontWeight: 500, color: "#24143099", width: 70, fontVariantNumeric: "tabular-nums", textAlign: "left", padding: pad, borderBottom: "1px solid #24143020" }}>{r.hour}</th>
            <td style={{ padding: pad, borderBottom: "1px solid #24143020" }}>
              {r.event && <span style={{ borderRadius: 6, fontWeight: 600, color: "#14351f", background: accent, padding: "2px 8px" }}>{r.event}</span>}
            </td>
          </tr>
        ))}
      </tbody>
    </table>
  );
}
